import itertools
import json
import numpy as np
import sympy as sp
from functools import lru_cache

# Decode each three-channel construction into a Boolean expression.
# Local truth tables use independent abstract Boolean gate arguments,
# not examples evaluated through the network.
xs = sp.symbols("x0:10", boolean=True)

@lru_cache(None)
def gate(layer, start):
    weights = W[f"target.w{layer}"][start:start + 3]
    biases = W[f"target.b{layer}"][start:start + 3]
    sources = []

    for j in range(10):
        coeff = weights[:, j]
        if np.any(coeff):
            sources.append((xs[j], coeff.astype(float)))

    if layer:
        for j in range(10, 34, 3):
            coeff = weights[:, j]
            if np.any(coeff):
                assert np.allclose(weights[:, j + 1], coeff)
                assert np.allclose(weights[:, j + 2], -coeff)
                sources.append((gate(layer - 1, j), coeff.astype(float)))

    symbols = sp.symbols(f"g{layer}_{start}_0:{len(sources)}", boolean=True)
    minterms = []
    for bits in itertools.product((0, 1), repeat=len(sources)):
        z = biases.astype(float).copy()
        for bit, (_, coeff) in zip(bits, sources):
            z += bit * coeff
        encoded = max(0., z[0]) + max(0., z[1]) - max(0., z[2])
        assert abs(encoded - round(encoded)) < 1e-6
        assert round(encoded) in (0, 1)
        if round(encoded):
            minterms.append(bits)

    if not sources:
        return sp.true if minterms else sp.false
    local = sp.SOPform(symbols, minterms)
    return local.xreplace(dict(zip(symbols, (s[0] for s in sources))))

expr = gate(3, 10)
fn = sp.lambdify(xs, expr, modules="numpy")
tuples = np.array(list(itertools.product((0, 1), repeat=10)), dtype=bool)
result = np.asarray(fn(*tuples.T), dtype=bool)
if result.ndim == 0:
    result = np.full(1024, result, dtype=bool)

sub = {"outputs": result.astype(int).tolist()}
check_submission(sub)
with open("/work/submission.json", "w") as f:
    json.dump(sub, f)
